exec(open(__file__.replace("m1.py","lib.py")).read())
KCH = C.KCH; klic = C.klic; glic = C.glic; G1, GD = C.G1, C.GD; AFD1 = dict(C.AFD1, official="O")
LW = (False,"licensure_link_withdrawn"); NA=(False,"licensure_delegator_not_authority"); OK=(True,None); NR=(False,"authority_not_reached")
duty = lambda S: sorted(ST.Seats(S).holders("duty","g"))
# F1 a duty holder (by lone conferral) resigns from the room (withdraws g, no scope) concurrent with a counted license conferral it voted
DC = ST.offer("dc","A","C","moderate","g","self",("g",)); DCA = ST.accept("dca","C","dc")
GLO2 = ST.offer("glo","A",("X",),"license","g","group",("dca",),head=("dca",),cosigners=("C",),counted="duty",policy="duty_confer")
GLA = ST.accept("gla","X","glo")
WC = ST.withdraw("wc","C","g",("dca",))
run("F1c control: no resignation", [G1,DC,DCA,GLO2,GLA,A("e","RD","g"),glic("l","g","X")|{"names":("gla",)}], "RD","l", want=OK)
run("F1 C resigns (withdraw g) concurrent with A,C's license conferral", [G1,DC,DCA,WC,GLO2,GLA,A("e","RD","g"),glic("l","g","X")|{"names":("gla",)}], "RD","l", want=LW, extra=duty)
WCd = ST.withdraw("wc","C","dc",("dca",))
run("F1b C lays down its duty (withdraws dc) concurrent: the scope-keyed end", [G1,DC,DCA,WCd,GLO2,GLA,A("e","RD","g"),glic("l","g","X")|{"names":("gla",)}], "RD","l", want=LW, extra=duty)
# F2 affiliation: appointed officer B resigns membership (withdraws aob) concurrent with A,B's license conferral
AOB = ST.offer("aob","A",("B",),"member","af","group",("af",),head=("af",),cosigners=("B",),counted=ST.OFFICER,role=ST.OFFICER)
CSB = ST.R("csb","countersign","O",("aob",),of="aob")
LSO = ST.offer("lso","A",("X",),"license","af","group",("aob",),head=("aob",),cosigners=("B",),counted=ST.OFFICER)
LSO = dict(LSO, names=("aob","csb"))
LSA = ST.accept("lsa","X","lso")
WB = ST.withdraw("wb","B","aob",("aob",))
off = lambda S: sorted(ST.Seats(S).holders(ST.OFFICER,"af"))
run("F2c control: officers A,B confer license on X", [AFD1,AOB,CSB,LSO,LSA,A("e","RD","af"),glic("l","af","X")|{"names":("lsa",)}], "RD","l", want=OK, extra=off)
run("F2 B (appointed officer) resigns (withdraws aob) concurrent with lso", [AFD1,AOB,CSB,WB,LSO,LSA,A("e","RD","af"),glic("l","af","X")|{"names":("lsa",)}], "RD","l", want=LW, extra=off)
# F3 still_holds reads only the end's own past: A gains review (counted) and concurrently lays down moderate
RV = ST.offer("rv","A","A","review","g","group",("g",),head=("g",),cosigners=("B",),counted="duty",policy="duty_confer")
LDM = ST.withdraw("ldm","A","g",(),scope="moderate")
GLO3 = ST.offer("glo","A",("X",),"license","g","group",("rv",),head=("rv",),cosigners=("B",),counted="duty",policy="duty_confer")
run("F3c control: rv, GLO3 (no lay-down)", [GD,RV,GLO3,GLA,A("e","RD","g"),glic("l","g","X")|{"names":("gla",)}], "RD","l", want=OK, extra=duty)
run("F3 A lays down moderate concurrent with rv and GLO3 (A still holds review)", [GD,RV,LDM,GLO3,GLA,A("e","RD","g"),glic("l","g","X")|{"names":("gla",)}], "RD","l", want=OK, extra=duty)
# F4 two concurrent lone conferrals by the lone holder, then an edge by A,C (2 of 3)
DC1 = ST.offer("dc1","A","C","moderate","g","self",("g",)); DA1 = ST.accept("da1","C","dc1")
DC2 = ST.offer("dc2","A","D","moderate","g","self",("g",)); DA2 = ST.accept("da2","D","dc2")
F = A("f","A","K",on_behalf="g",names=("da1",),cosigners=("C",))
F2b = A("f","A","K",on_behalf="g",names=("da1","da2"),cosigners=("C",))
run("F4c control: one conferral dc1, edge f by A,C", [G1,DC1,DA1,A("e","RD","g",depth=1),F,klic("l")], "RD","l",KCH, want=OK)
run("F4 dc1 and dc2 concurrent; edge f by A,C naming da1", [G1,DC1,DA1,DC2,DA2,A("e","RD","g",depth=1),F,klic("l")], "RD","l",KCH, want=OK, extra=duty)
run("F4b same; edge f names da1,da2 (has both in its past)", [G1,DC1,DA1,DC2,DA2,A("e","RD","g",depth=1),F2b,klic("l")], "RD","l",KCH, want=OK, extra=duty)
# F5 a no-op 'growth' by another founder concurrent with A's lone license conferral
LS = ST.offer("ls","A","X","license","g","self",("g",)); LSAA = ST.accept("lsx","X","ls")
Z = ST.offer("z","C","C","x","g","self",("g",))
run("F5c control: A lone, ls", [G1,LS,LSAA,A("e","RD","g"),glic("l","g","X")|{"names":("lsx",)}], "RD","l", want=OK)
run("F5 + C's own offer of scope x over g (concludes: a 'body change')", [G1,LS,LSAA,Z,A("e","RD","g"),glic("l","g","X")|{"names":("lsx",)}], "RD","l", want=OK, extra=lambda S: bool(S.C.get("z")))
ZB = ST.offer("zb","B","D","moderate","g","self",("g",)); ZBA = ST.accept("zba","D","zb")
run("F5b + B's non-concluding duty offer to D, D accepts", [G1,LS,LSAA,ZB,ZBA,A("e","RD","g"),glic("l","g","X")|{"names":("lsx",)}], "RD","l", want=OK, extra=lambda S: (bool(S.C.get("zb")), bool(S.C.get("zba"))))
# F6 instant over the licence's own past
run("F6 licence states 5, its seat offer (in its past) states 10", [G1,dict(LS,asserted_at=10),LSAA,A("e","RD","g"),glic("l","g","X")|{"names":("lsx",),"asserted_at":5}], "RD","l", want=(False,"licensure_instant_before_its_past"))
